mapper.select:
select t.id,t.plan_id,t.plan_name,t.team_id,t.factory_id,t.task_begin_date,t.task_end_date,t.`status`,t.remark,t.create_time,t.cur_order from safety_spot_check_task t where 1 = 1 and t.id in (select max(id) from safety_spot_check_task a group by a.plan_id,a.factory_id)
and t.plan_id = #{planId}
and t.factory_id = #{factoryId}
order by t.task_begin_date desc

select t.id,t.plan_id,t.plan_name,t.team_id,t.factory_id,t.task_begin_date,t.task_end_date,t.`status`,t.remark,t.create_time,t.cur_order
from safety_spot_check_task t
where 1 = 1
  and t.task_begin_date = #{taskBeginDate}

    and t.plan_id = #{planId}


    and t.factory_id = #{factoryId}

select r.task_id as id, count(1) device_num, sum(r.status) check_num, count(1) - sum(r.status) uncheck_num, sum(IFNULL(device_status, 0)) exception_num, round((sum(r.status) / count(1)) * 100, 2) check_rate, sum(IFNULL(r.is_reform, 0)) reform_num, sum(IFNULL(r.validate_status, 0)) validate_num, sum(IFNULL(r.delay_check_flag, 0)) spot_delay_num, sum(IFNULL(r.delay_reform_flag, 0)) reform_delay_num, case when sum(IFNULL(device_status, 0)) = 0 then 0 else round(sum(IFNULL(r.is_reform, 0)) / sum(IFNULL(device_status, 0)) * 100, 2) end reform_rate, case when count(1) = 0 then 0 else round(sum(IFNULL(r.delay_check_flag, 0)) / count(1) * 100, 2) end spot_delay_rate, case when sum(IFNULL(r.is_reform, 0)) = 0 then 0 else round(sum(IFNULL(r.delay_reform_flag, 0)) / sum(IFNULL(r.is_reform, 0)) * 100, 2) end reform_delay_rate from safety_spot_check_record r where r.task_id in
#{item}
group by r.task_id

  select t.id,t.plan_id,t.plan_name,t.team_id,t.factory_id,t.task_begin_date,t.task_end_date,t.`status`
          ,t.remark,t.cur_order,m.field_name factory_name,m1.field_name team_name,m2.id device_type_id
          ,m2.field_name device_type,CONCAT(p.cycle,'天1次') cycle_desc
  from safety_spot_check_task t
  left JOIN safety_field_manage m on m.id = t.factory_id
  left join safety_field_manage m1 on m1.id = t.team_id
  left join safety_field_manage m2 on m2.id = m1.parent_id
  left join safety_spot_check_plan p on p.id = t.plan_id
where 1 = 1

    and t.factory_id = #{factoryId}


    and m2.id = #{deviceTypeId}


    and m2.field_name like CONCAT('%',#{deviceType},'%')


    and t.team_id = #{teamId}


    and m1.field_name like CONCAT('%',#{teamName},'%')


    and p.cycle = #{cycle}



    and t.task_end_date >= #{taskBeginDate}




    AND T.task_begin_date <= #{taskEndDate}


order by task_begin_date desc,plan_id asc



      limit ${offset}, ${limit}


      limit ${limit}

select count(1)
from safety_spot_check_task t
left JOIN safety_field_manage m on m.id = t.factory_id
left join safety_field_manage m1 on m1.id = t.team_id
left join safety_field_manage m2 on m2.id = m1.parent_id
left join safety_spot_check_plan p on p.id = t.plan_id
where 1 = 1

      and t.factory_id = #{factoryId}


      and m2.id = #{deviceTypeId}


      and m2.field_name like CONCAT('%',#{deviceType},'%')


      and t.team_id = #{teamId}


      and m1.field_name like CONCAT('%',#{teamName},'%')


      and p.cycle = #{cycle}



    and t.task_end_date >= #{taskBeginDate}




    AND T.task_begin_date <= #{taskEndDate}

SELECT type_id,max(type_name) type_name,team_id,max(team_name) team_name, count(1) device_num,sum(`status`) check_num, count(1)-sum(`status`) uncheck_num, task_begin_date,max(task_end_date) task_end_date,plan_id ,CONCAT(round(sum(`status`)*100/count(1)),'%') check_rate FROM (SELECT r.id,r.device_id,r.`status`,r.device_status,r.is_reform,r.validate_status,r.task_id, t.team_id,m.field_name team_name,t.task_begin_date,t.task_end_date,m.parent_id type_id, m1.field_name type_name,t.plan_id FROM safety_spot_check_record r LEFT JOIN safety_spot_check_task t ON r.task_id = t.id LEFT JOIN safety_field_manage m ON t.team_id = m.id LEFT JOIN safety_field_manage m1 ON m.parent_id = m1.id WHERE 1 = 1 and m1.field_name is not null
and t.task_begin_date <= #{dayDate} and t.task_end_date >= #{dayDate}
and t.task_begin_date <= #{endDate}
and t.task_end_date >= #{beginDate}
and r.plan_check_emp_no like concat('%',#{checkEmpNo},'%')
) AS cur group by type_id,team_id,plan_id,task_begin_date order by task_begin_date desc

select t.id,t.plan_id,t.plan_name,t.team_id,t.factory_id,t.task_begin_date,t.task_end_date,t.`status` ,t.remark,t.cur_order,m.field_name factory_name,m1.field_name team_name,m2.id device_type_id ,m2.field_name device_type,CONCAT(p.cycle,'') cycle_desc from safety_spot_check_task t left JOIN safety_field_manage m on m.id = t.factory_id left join safety_field_manage m1 on m1.id = t.team_id left join safety_field_manage m2 on m2.id = m1.parent_id left join safety_spot_check_plan p on p.id = t.plan_id where 1 = 1 and t.task_end_date > DATE_FORMAT(NOW(), '%Y-%m-%d')
and t.task_begin_date <= #{taskEndDate}
and t.task_end_date >= #{taskBeginDate}
and t.plan_id in
#{item}

update.foreach:
update safety_spot_check_task
   set task_end_date = #{item.taskEndDate}

       , task_begin_date = #{taskBeginDate}

where id = #{item.id}

mapper.select:
SELECT * FROM safety_spot_check_device_info d WHERE (d.team_id,d.factory_id) in (SELECT t.team_id,t.factory_id from safety_spot_check_task t where t.id= #{taskId})
and d.id in (SELECT r.device_id FROM safety_spot_check_record r where r.task_id = #{taskId})
AND d.delete_falg = #{deleteFalg}
